import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,mkdirSync,readFileSync,rmSync,writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {startInstance} from './fixtures/controlled-instance.mjs';
import {DatabaseSync} from 'node:sqlite';
import {SecretRequests} from '../dist/secret-requests.js';
import {Instance} from '../dist/instance.js';
const wait=async fn=>{for(let i=0;i<400;i++){const value=await fn();if(value)return value;await new Promise(resolve=>setTimeout(resolve,20));}throw Error('Timed out');};
const secret='synthetic-client-secret-81283',refresh='synthetic-refresh-token-71293';

async function fixture(mode='direct',extra={}) {
 const dir=mkdtempSync(join(tmpdir(),'staf-guided-gmail-')),path=join(dir,'instance.sqlite'),seen=[],google=[];mkdirSync(join(dir,'auth'));const legacy=Buffer.from(JSON.stringify({email:'legacy@example.test',clientId:'legacy-client',clientSecret:'synthetic-legacy-client-secret',refreshToken:'synthetic-legacy-refresh-token'}));writeFileSync(join(dir,'auth','gmail.json'),legacy);
 const options={dataDir:dir,env:{},gmailPollIntervalMs:3600000,gmailRequest:async(url,options={})=>{google.push({url:String(url),body:String(options.body??'')});if(extra.google)return extra.google(url,options);return new URL(url).hostname==='oauth2.googleapis.com'?Response.json({access_token:'synthetic-access-token-7415',refresh_token:refresh,scope:'https://www.googleapis.com/auth/gmail.readonly',token_type:'Bearer'}):Response.json({emailAddress:'owner@example.test',historyId:'100'});},providerFactory:async()=>({name:'synthetic',capabilities:{toolCalls:true},async complete(messages,_tools,opts){seen.push(JSON.stringify(messages));const turn=messages.slice(messages.findLastIndex(item=>item.role==='user')+1);if((extra.task || opts.currentUserInput==='Set up Gmail')&&!turn.some(item=>item.role==='tool')){const guest=mode==='code';return {role:'assistant',content:null,tool_calls:[{id:'setup',type:'function',function:guest?{name:'code_mode',arguments:JSON.stringify({source:'return await capabilities.guide_gmail_setup({});'})}:{name:'guide_gmail_setup',arguments:'{}'}}]};}return {role:'assistant',content:'Done'};}})};
 let app=startInstance(path,0,options),port=await app.listen(),token;
 const call=async(route,body,auth=token)=>{const response=await fetch(`http://127.0.0.1:${port}${route}`,{method:body?'POST':'GET',headers:{...(auth?{Authorization:`Bearer ${auth}`} : {}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const value=await response.json();return {status:response.status,value};};
 token=(await call('/api/pair',{code:app.code},'')).value.token;const bot=(await call('/api/bots',{name:'Agent',provider:'live',model:'fixture',toolMode:mode})).value;if(extra.task)await call('/api/tasks',{id:'setup',botId:bot.id,objective:'Set up Gmail'});else{await call('/api/commands',{id:'setup',botId:bot.id,content:'Set up Gmail'});await wait(async()=>(await call('/api/commands/setup')).value.state==='completed');}const q=await wait(async()=>(await call('/api/question-sets')).value.find(item=>item.workId==='setup'));assert.ok(q);assert.equal((await call(`/api/question-sets/${q.id}/draft`,{answers:[{choices:[],writeIn:'owner@example.test'},{choices:[],writeIn:'synthetic-client-id'},null,null]})).status,200);if(extra.select){await call('/api/secrets/add',{name:'Existing Gmail client',purpose:'Synthetic client',value:secret});const existing=(await call('/api/secrets')).value.find(item=>item.name==='Existing Gmail client');assert.equal((await call(`/api/question-sets/${q.id}/secret/2/select`,{name:existing.name,revision:existing.revision})).status,200);}else {if(extra.name)await call('/api/secrets/add',{name:'Gmail OAuth client secret',purpose:'Earlier synthetic secret',value:'synthetic-old-client-value'});assert.equal((await call(`/api/question-sets/${q.id}/secret/2/save`,{value:secret,...(extra.name?{name:'Corrected Gmail client'}:{})})).status,200);}
 return {dir,path,legacy,seen,google,bot,q,call,get token(){return token;},set token(value){token=value;},get app(){return app;},async restart(before){await app.close();before?.();app=startInstance(path,0,options);port=await app.listen();},async close(){await app.close();rmSync(dir,{recursive:true,force:true});}};
}
const callback=url=>{const auth=new URL(url),redirect=new URL(auth.searchParams.get('redirect_uri'));redirect.searchParams.set('state',auth.searchParams.get('state'));redirect.searchParams.set('code','synthetic-code');return redirect;};

test('guided Gmail setup connects through synthetic Google in every tool mode',async()=>{
 for(const mode of ['direct','hybrid','code']){const f=await fixture(mode);try{const preview=(await f.call(`/api/question-sets/${f.q.id}/gmail-preview`)).value;assert.equal(preview.secret.name,'Gmail OAuth client secret');assert.ok(!JSON.stringify(preview).includes(secret));const start=await f.call(`/api/question-sets/${f.q.id}/gmail-start`,{...preview,confirm:true,confirmDisplacements:false});assert.equal(start.status,200,JSON.stringify(start.value));assert.equal((await f.call(`/api/question-sets/${f.q.id}/gmail-authorization`)).value.url,start.value.url);assert.equal((await f.call('/api/plugins')).value.find(item=>item.id==='gmail').connected,false);assert.equal((await fetch(callback(start.value.url))).status,200);const gmail=(await f.call('/api/plugins')).value.find(item=>item.id==='gmail');assert.equal(gmail.connected,true);assert.equal(gmail.enabled,false);assert.deepEqual(gmail.agentAccessIds,[]);const q=(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id);assert.equal(q.gmailSetup,'connected');await f.call(`/api/question-sets/${f.q.id}/submit`,{});await wait(async()=>(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).continuationState==='completed');assert.ok(f.seen.some(item=>item.includes('connected')));assert.ok(!JSON.stringify(f.seen).includes(secret));assert.ok(!JSON.stringify(f.seen).includes(refresh));assert.ok(!JSON.stringify(f.seen).includes('synthetic-access-token-7415'));assert.ok(!JSON.stringify(f.google).includes('synthetic-legacy-client-secret'));assert.ok(!readFileSync(f.path).includes(Buffer.from('synthetic-access-token-7415')));assert.ok(!readFileSync(f.path).includes(Buffer.from(secret)));assert.ok(!readFileSync(f.path).includes(Buffer.from(refresh)));assert.deepEqual(readFileSync(join(f.dir,'auth','gmail.json')),f.legacy);await f.restart();assert.equal((await f.call('/api/plugins')).value.find(item=>item.id==='gmail').connected,true);}finally{await f.close();}}
});

test('guided Gmail preview expires when a reviewed grant changes or the selection is replaced',async()=>{
 const f=await fixture();try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value;await f.call('/api/secrets/replace',{name:preview.secret.name,revision:preview.secret.revision,value:'synthetic-replacement',confirm:true});assert.notEqual((await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false})).status,200);assert.equal(f.google.length,0);}finally{await f.close();}
});

test('guided Gmail authorization fails closed when the initiating client is revoked',async()=>{
 const f=await fixture();try{const other=(await f.call('/api/pair',{code:f.app.issueCode()},'')).value.token,preview=(await f.call(`/api/question-sets/${f.q.id}/gmail-preview`)).value,start=await f.call(`/api/question-sets/${f.q.id}/gmail-start`,{...preview,confirm:true,confirmDisplacements:false});assert.equal(start.status,200,JSON.stringify(start.value));const clients=(await f.call('/api/clients',undefined,other)).value;await f.call(`/api/clients/${clients.find(item=>!item.current).id}/revoke`,{},other);assert.equal((await fetch(callback(start.value.url))).status,400);assert.equal(f.google.length,0);assert.equal((await f.call('/api/plugins',undefined,other)).value.find(item=>item.id==='gmail').connected,false);}finally{await f.close();}
});


test('guided setup reports a Google failure and retains it after restart',async()=>{
 const f=await fixture('direct',{google:async()=>new Response('denied',{status:400})});try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal(start.status,200);assert.equal((await fetch(callback(start.value.url))).status,400);assert.equal((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).gmailSetup,'failed');assert.equal((await f.call('/api/plugins')).value.find(item=>item.id==='gmail').connected,false);await f.restart();assert.equal((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).gmailSetup,'failed');assert.equal((await f.call('/api/plugins')).value.find(item=>item.id==='gmail').connected,false);}finally{await f.close();}
});

test('guided setup never reports connected if the plugin commit fails',async()=>{
 const f=await fixture();try{await f.restart(()=>{const db=new DatabaseSync(f.path);db.exec("CREATE TRIGGER fail_guided_gmail BEFORE INSERT ON plugin_connections WHEN NEW.plugin_id='gmail' BEGIN SELECT RAISE(ABORT,'synthetic commit failure'); END");db.close();});const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal(start.status,200);assert.equal((await fetch(callback(start.value.url))).status,400);assert.equal((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).gmailSetup,'failed');assert.equal((await f.call('/api/plugins')).value.find(item=>item.id==='gmail').connected,false);await f.restart();assert.equal((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).gmailSetup,'failed');assert.equal((await f.call('/api/plugins')).value.find(item=>item.id==='gmail').connected,false);assert.ok(!readFileSync(f.path).includes(Buffer.from(secret)));}finally{await f.close();}
});

test('review requires exact displacement confirmation and rejects a stale grant decision',async()=>{
 const f=await fixture();let store;try{const route=`/api/question-sets/${f.q.id}`;store=new SecretRequests(f.dir,false);store.add({name:'Prior Gmail use',purpose:'Prior synthetic use',value:'synthetic-prior-secret'});const prior=store.names().find(item=>item.name==='Prior Gmail use'),destination=JSON.stringify(['https://oauth2.googleapis.com/token','https://gmail.googleapis.com','owner@example.test']),target=store.target('gmail.client',destination);store.grant({name:prior.name,revision:prior.revision,integration:'gmail.client',destination,version:target.version,previous:null,confirmDisplacement:false});const preview=(await f.call(route+'/gmail-preview')).value;assert.equal(preview.clientTarget.current.name,'Prior Gmail use');assert.notEqual((await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false})).status,200);assert.equal(store.resolve({integration:'gmail.client',destination}),'synthetic-prior-secret');const grant=store.grants().find(item=>item.integration==='gmail.client');assert.equal(store.revoke(grant),true);assert.notEqual((await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:true})).status,200);assert.equal(f.google.length,0);const fresh=(await f.call(route+'/gmail-preview')).value;assert.equal((await f.call(route+'/gmail-start',{...fresh,confirm:true,confirmDisplacements:false})).status,200);}finally{store?.close();await f.close();}
});

test('revoking the selected Gmail grant prevents token dispatch',async()=>{
 const f=await fixture();try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal(start.status,200);const grant=(await f.call('/api/secret-grants')).value.find(item=>item.integration==='gmail.client');assert.equal((await f.call('/api/secret-grants/revoke',{...grant,confirm:true})).status,200);assert.equal((await fetch(callback(start.value.url))).status,400);assert.equal(f.google.length,0);assert.notEqual((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).gmailSetup,'connected');}finally{await f.close();}
});

test('the exact displaced Gmail grant must be confirmed before it changes',async()=>{
 const f=await fixture();let store;try{store=new SecretRequests(f.dir,false);store.add({name:'Old client grant',purpose:'Synthetic old',value:'synthetic-old-client'});const old=store.names().find(item=>item.name==='Old client grant'),destination=JSON.stringify(['https://oauth2.googleapis.com/token','https://gmail.googleapis.com','owner@example.test']),target=store.target('gmail.client',destination);store.grant({name:old.name,revision:old.revision,integration:'gmail.client',destination,version:target.version,previous:null,confirmDisplacement:false});const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value;assert.equal(preview.clientTarget.current.name,'Old client grant');assert.notEqual((await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false})).status,200);const start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:true});assert.equal(start.status,200,JSON.stringify(start.value));assert.equal(store.resolve({integration:'gmail.client',destination}),secret);assert.equal((await fetch(callback(start.value.url))).status,200);const grants=(await f.call('/api/secret-grants')).value;assert.ok(grants.some(item=>item.integration==='gmail.client' && item.name==='Gmail OAuth client secret'));assert.ok(!grants.some(item=>item.integration==='gmail.client' && item.name==='Old client grant'));}finally{store?.close();await f.close();}
});

test('grant revocation during token exchange stops the profile check and commit',async()=>{
 let release,started;const gate=new Promise(resolve=>release=resolve),entered=new Promise(resolve=>started=resolve);let profileCalls=0;
 const f=await fixture('direct',{google:async url=>{if(new URL(url).hostname==='oauth2.googleapis.com'){started();await gate;return Response.json({access_token:'synthetic-access-token-7415',refresh_token:refresh,scope:'https://www.googleapis.com/auth/gmail.readonly',token_type:'Bearer'});}profileCalls++;return Response.json({emailAddress:'owner@example.test',historyId:'100'});}});
 try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});const pending=fetch(callback(start.value.url));await entered;const grant=(await f.call('/api/secret-grants')).value.find(item=>item.integration==='gmail.client');assert.equal((await f.call('/api/secret-grants/revoke',{...grant,confirm:true})).status,200);release();assert.equal((await pending).status,400);assert.equal(profileCalls,0);assert.equal((await f.call('/api/plugins')).value.find(item=>item.id==='gmail').connected,false);}finally{release();await f.close();}
});

test('restarting an in-flight guided authorization leaves an interrupted request without replay',async()=>{
 let started;const entered=new Promise(resolve=>started=resolve);let requests=0;
 const f=await fixture('direct',{google:async(_url,options)=>{requests++;started();await new Promise((_,reject)=>options.signal.addEventListener('abort',()=>reject(Error('aborted')),{once:true}));throw Error('Unexpected');}});
 try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});const pending=fetch(callback(start.value.url));await entered;await f.restart();assert.equal((await pending).status,400);assert.equal((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).gmailSetup,'interrupted');assert.equal((await f.call('/api/plugins')).value.find(item=>item.id==='gmail').connected,false);assert.equal(requests,1);}finally{await f.close();}
});


test('guided reconnection keeps the same account agent and model permissions',async()=>{
 const f=await fixture();try{await f.restart(()=>{const instance=new Instance(f.path);instance.plugins.gmailConnect({email:'owner@example.test',clientId:'old-client'},'90');instance.plugins.gmailSetAccess(f.bot.id,true);instance.plugins.gmailSetModelAccess(f.bot.id,'live','fixture',true);instance.plugins.gmailSetWorkModelAccess(f.bot.id,'live','fixture',true);instance.plugins.gmailDisconnect();instance.close();});const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal(start.status,200,JSON.stringify(start.value));assert.equal((await fetch(callback(start.value.url))).status,200);const gmail=(await f.call('/api/plugins')).value.find(item=>item.id==='gmail');assert.ok(gmail.agentAccessIds.includes(f.bot.id));assert.ok(gmail.modelAccess.some(item=>item.botId===f.bot.id && item.provider==='live' && item.model==='fixture'));assert.ok(gmail.workModelAccess.some(item=>item.botId===f.bot.id && item.provider==='live' && item.model==='fixture'));assert.equal(gmail.enabled,false);}finally{await f.close();}
});

