test('a revoked and restored grant invalidates an earlier guided review',async()=>{
 const f=await fixture();let store;try{store=new SecretRequests(f.dir,false);store.add({name:'Prior',purpose:'Synthetic',value:'synthetic-prior-value'});const prior=store.names().find(item=>item.name==='Prior'),destination=JSON.stringify(['https://oauth2.googleapis.com/token','https://gmail.googleapis.com','owner@example.test']);let target=store.target('gmail.client',destination);store.grant({name:prior.name,revision:prior.revision,integration:'gmail.client',destination,version:target.version,previous:null,confirmDisplacement:false});const route=`/api/question-sets/${f.q.id}`,reviewed=(await f.call(route+'/gmail-preview')).value;const old=store.grants().find(item=>item.integration==='gmail.client');assert.equal(store.revoke(old),true);target=store.target('gmail.client',destination);store.grant({name:prior.name,revision:prior.revision,integration:'gmail.client',destination,version:target.version,previous:null,confirmDisplacement:false});assert.notEqual((await f.call(route+'/gmail-start',{...reviewed,confirm:true,confirmDisplacements:true})).status,200);assert.equal(f.google.length,0);assert.equal(store.resolve({integration:'gmail.client',destination}),'synthetic-prior-value');}finally{store?.close();await f.close();}
});

