test('a legacy-only connected account can be reconnected without importing its file',async()=>{
 const f=await fixture();try{await f.restart(()=>{const instance=new Instance(f.path);instance.plugins.gmailConnect({email:'owner@example.test',clientId:'legacy-client'},'90');instance.plugins.gmailSetAccess(f.bot.id,true);instance.close();});const legacy=readFileSync(join(f.dir,'auth','gmail.json')),before=(await f.call('/api/secret-grants')).value;assert.equal(before.filter(item=>item.integration.startsWith('gmail.')).length,0);const route=`/api/question-sets/${f.q.id}`,review=await f.call(route+'/gmail-preview');assert.equal(review.status,200,JSON.stringify(review.value));assert.equal(review.value.credentialsAvailable,false);assert.equal(review.value.connection.connected,true);const start=await f.call(route+'/gmail-start',{...review.value,confirm:true,confirmDisplacements:false});assert.equal(start.status,200,JSON.stringify(start.value));assert.equal((await fetch(callback(start.value.url))).status,200);assert.ok((await f.call('/api/plugins')).value.find(item=>item.id==='gmail').agentAccessIds.includes(f.bot.id));assert.deepEqual(readFileSync(join(f.dir,'auth','gmail.json')),legacy);await f.restart();assert.equal((await f.call('/api/plugins')).value.find(item=>item.id==='gmail').connected,true);assert.deepEqual(readFileSync(join(f.dir,'auth','gmail.json')),legacy);}finally{await f.close();}
});

test('a reconnect commit failure reports failure and retains the existing account after restart',async()=>{
 const f=await fixture();try{await f.restart(()=>{const instance=new Instance(f.path);instance.plugins.gmailConnect({email:'owner@example.test',clientId:'old-client'},'90');instance.plugins.gmailSetAccess(f.bot.id,true);instance.plugins.gmailSetEnabled(true);instance.close();const db=new DatabaseSync(f.path);db.exec("CREATE TRIGGER fail_guided_reconnect BEFORE UPDATE OF config ON plugin_connections WHEN NEW.plugin_id='gmail' BEGIN SELECT RAISE(ABORT,'synthetic reconnect commit failure'); END");db.close();});const route=`/api/question-sets/${f.q.id}`,review=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...review,confirm:true,confirmDisplacements:false});assert.equal(start.status,200,JSON.stringify(start.value));assert.equal((await fetch(callback(start.value.url))).status,400);let gmail=(await f.call('/api/plugins')).value.find(item=>item.id==='gmail');assert.equal(gmail.config.clientId,'old-client');assert.equal(gmail.enabled,false);assert.ok(gmail.agentAccessIds.includes(f.bot.id));assert.equal((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).gmailSetup,'failed');await f.restart();gmail=(await f.call('/api/plugins')).value.find(item=>item.id==='gmail');assert.equal(gmail.config.clientId,'old-client');assert.equal(gmail.enabled,false);assert.equal((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).gmailSetup,'failed');assert.deepEqual(readFileSync(join(f.dir,'auth','gmail.json')),f.legacy);}finally{await f.close();}
});

test('authorization evidence survives grant revocation and accompanies submit and dismiss',async()=>{
 for(const decision of ['submit','dismiss'])for(const mode of ['direct','hybrid','code']){const f=await fixture(mode);try{const route=`/api/question-sets/${f.q.id}`,review=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...review,confirm:true,confirmDisplacements:false});assert.equal((await fetch(callback(start.value.url))).status,200);let q=(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id);assert.equal(q.gmailAuthorization,'succeeded');assert.equal(q.gmailConnection.status,'credentials_available');assert.equal(q.gmailConnection.enabled,false);const grant=(await f.call('/api/secret-grants')).value.find(item=>item.integration==='gmail.client');assert.equal((await f.call('/api/secret-grants/revoke',{...grant,confirm:true})).status,200);await f.restart();q=(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id);assert.equal(q.gmailAuthorization,'succeeded');assert.equal(q.gmailSetup,'connected');assert.equal(q.gmailConnection.status,'credentials_unavailable');const result=await f.call(route+'/'+decision,{});assert.equal(result.value.result.gmailAuthorization,'succeeded');assert.equal(result.value.result.gmailConnectionAtResolution.status,'credentials_unavailable');assert.equal(result.value.result.gmailSetup,'connected');await wait(async()=>(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).continuationState==='completed');assert.ok(f.seen.some(item=>item.includes('succeeded')&&item.includes('credentials_unavailable')));await f.restart();q=(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id);assert.equal(q.result.gmailAuthorization,'succeeded');assert.equal(q.gmailConnection.status,'credentials_unavailable');assert.ok(!JSON.stringify(f.seen).includes(secret));}finally{await f.close();}}
});
